func (u *TopupMailUpsertBulk) Update(set func(*TopupMailUpsert)) *TopupMailUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&TopupMailUpsert{UpdateSet: update})
	}))
	return u
}

